 for(const [d,s] of [[7200,24],[1800,30]])put('connect',`A fictional ship sails ${n(d)} km at a steady ${s} km per hour. How many hours does the trip take?`,d/s,tab('A trip',[['distance',`${n(d)} km`],['speed',`${s} km per hour`]]),`${n(d)} ÷ ${s} = ${d/s} hours.`);
 put('connect','A fictional town receives 120,000 dollars in remittances from 300 families. On average, how many dollars per family is that?',400,tab('A town',[['remittances','120,000 dollars'],['families','300']]),'120,000 ÷ 300 = 400 dollars.');
